import React, { useState } from "react";
import ProductForm from "./components/ProductForm";
import ProductList from "./components/ProductList";
import SettingsForm from "./components/SettingsForm"; // 1. Importar
import api from "./api";

function App() {
  const [refreshKey, setRefreshKey] = useState(0);

  // 2. Adicionar estado para as configurações globais
  const [globalSettings, setGlobalSettings] = useState({
    iof_percent: "3.5", // Valor padrão, pode ser o que você mais usa
    taxa_dolar: "5.30"   // Valor padrão
  });

  const handleProductSaved = () => {
    setRefreshKey((prevKey) => prevKey + 1);
  };

  return (
    <div className="App">
      <h1>Gerenciador de Compra e Venda de Acessórios Musicais</h1>

      {/* 3. Adicionar o formulário de configurações */}
      <SettingsForm
        settings={globalSettings}
        onSettingsChange={setGlobalSettings}
      />

      {/* 4. Passar as configurações para o ProductForm */}
      <ProductForm
        api={api}
        onProductSaved={handleProductSaved}
        globalSettings={globalSettings}
      />

      <ProductList api={api} key={refreshKey} />
    </div>
  );
}

export default App;
